<script lang='ts'>import {page} from '$app/stores';import {dummyPatients} from '$lib/data/dummyPatients';import {dummyWorkflow} from '$lib/data/dummyWorkflow';import Timeline from '$lib/components/Timeline.svelte';$:p=dummyPatients.find(x=>x.id===$page.params.id) || dummyPatients[0];let note='';function save(){localStorage.setItem('doctorNotes',JSON.stringify({[p.id]:note}));}</script><h1 class='text-xl font-bold'>{p.name}</h1><p>{p.diagnosis} {p.stage} · {p.technique}</p><Timeline items={dummyWorkflow}/><textarea class='w-full border rounded-xl p-2' bind:value={note} placeholder='Catatan SOAP'></textarea><button class='px-3 py-2 rounded-xl bg-medical text-white' on:click={save}>Simpan catatan</button>
